// Prints lib/Games/SudokuBank.h: build/test/games_core/SudokuBankGen > lib/Games/SudokuBank.h
#include <chrono>
#include <cstdio>

#include "SudokuSolver.h"

int main() {
  constexpr int PER_LEVEL = 32;
  static const char* const NAMES[] = {"Easy", "Medium", "Hard", "Expert"};
  printf(
      "#pragma once\n\n"
      "// Generated by test/games_core/SudokuBankGen.cpp. Every puzzle has one solution and\n"
      "// grades exactly as its level (host-tested); newGame() reshapes them by seed.\n\n"
      "#include \"SudokuSolver.h\"\n\n"
      "namespace sudoku {\n\n"
      "constexpr int BANK_PER_LEVEL = %d;\n\n"
      "constexpr char BANK[LEVEL_COUNT][BANK_PER_LEVEL][CELLS + 1] = {\n",
      PER_LEVEL);
  sudoku::Workspace work;
  for (int level = 0; level < sudoku::LEVEL_COUNT; ++level) {
    uint32_t rng = 0x5EED0000u + static_cast<uint32_t>(level);
    const auto t0 = std::chrono::steady_clock::now();
    int attempts = 0;
    printf("    {\n        // %s\n", NAMES[level]);
    for (int n = 0; n < PER_LEVEL;) {
      sudoku::Puzzle p;
      ++attempts;
      if (!sudoku::generate(p, static_cast<sudoku::Level>(level), work, rng, 1)) continue;
      printf("        \"");
      for (int c = 0; c < sudoku::CELLS; ++c) putchar('0' + p.given[c]);
      printf("\",  // %d clues\n", p.clues);
      ++n;
    }
    printf("    },\n");
    const double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
    fprintf(stderr, "%s: %d attempts, %.2f ms per attempt\n", NAMES[level], attempts, ms / attempts);
  }
  printf("};\n\n}  // namespace sudoku\n");
  return 0;
}
